import{_ as t,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"搜索 Linux 中的文件和文件夹的四种简单方法 | LCTT x X-CMD","titleTemplate":false,"description":"搜索 Linux 中的文件和文件夹的四种简单方法 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"搜索 Linux 中的文件和文件夹的四种简单方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"搜索 Linux 中的文件和文件夹的四种简单方法 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181203 Four Easy Ways to Search Or Find Files And Folders in Linux","title":"搜索 Linux 中的文件和文件夹的四种简单方法","tag":"201812","desc":""},"relativePath":"201812/20181203 Four Easy Ways to Search Or Find Files And Folders in Linux.md","filePath":"[post].md"}'),h={name:"201812/20181203 Four Easy Ways to Search Or Find Files And Folders in Linux.md"};function c(g,s,u,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="搜索-linux-中的文件和文件夹的四种简单方法" tabindex="-1">搜索 Linux 中的文件和文件夹的四种简单方法 <a class="header-anchor" href="#搜索-linux-中的文件和文件夹的四种简单方法" aria-label="Permalink to “搜索 Linux 中的文件和文件夹的四种简单方法”">​</a></h1><p>Linux 管理员一天都不能离开搜索文件，因为这是他们的日常活动。了解一些搜索的东西是不错的，因为这能帮助你在命令行服务器中工作。这些命令记忆起来不复杂，因为它们使用的是标准语法。</p><p>可以通过四个 Linux 命令啦执行此操作，每个命令都有自己独特的功能。</p><h3 id="方法-1-使用-find-命令在-linux-中搜索文件和文件夹" tabindex="-1">方法 1：使用 find 命令在 Linux 中搜索文件和文件夹 <a class="header-anchor" href="#方法-1-使用-find-命令在-linux-中搜索文件和文件夹" aria-label="Permalink to “方法 1：使用 find 命令在 Linux 中搜索文件和文件夹”">​</a></h3><p><code>find</code> 命令被广泛使用，并且是在 Linux 中搜索文件和文件夹的著名命令。它搜索当前目录中的给定文件，并根据搜索条件递归遍历其子目录。</p><p>它允许用户根据大小、名称、所有者、组、类型、权限、日期和其他条件执行所有类型的文件搜索。</p><p>运行以下命令以在系统中查找给定文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -iname &quot;sshd_config&quot;</span></span>
<span class="line"><span>/etc/ssh/sshd_config</span></span></code></pre></div><p>运行以下命令以查找系统中的给定文件夹。要在 Linux 中搜索文件夹，我们需要使用 <code>-type</code> 参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type d -iname &quot;ssh&quot;</span></span>
<span class="line"><span>/usr/lib/ssh</span></span>
<span class="line"><span>/usr/lib/go/src/cmd/vendor/golang.org/x/crypto/ssh</span></span>
<span class="line"><span>/usr/lib/go/pkg/linux_amd64/cmd/vendor/golang.org/x/crypto/ssh</span></span>
<span class="line"><span>/etc/ssh</span></span></code></pre></div><p>使用通配符搜索系统上的所有文件。我们将搜索系统中所有以 <code>.config</code> 为扩展名的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -name &quot;*.config&quot;</span></span>
<span class="line"><span>/usr/lib/mono/gac/avahi-sharp/1.0.0.0__4d116c78973743f5/avahi-sharp.dll.config</span></span>
<span class="line"><span>/usr/lib/mono/gac/avahi-ui-sharp/0.0.0.0__4d116c78973743f5/avahi-ui-sharp.dll.config</span></span>
<span class="line"><span>/usr/lib/python2.7/config/Setup.config</span></span>
<span class="line"><span>/usr/share/git/mw-to-git/t/test.config</span></span>
<span class="line"><span>/var/lib/lightdm/.config</span></span>
<span class="line"><span>/home/daygeek/.config</span></span>
<span class="line"><span>/root/.config</span></span>
<span class="line"><span>/etc/skel/.config</span></span></code></pre></div><p>使用以下命令格式在系统中查找空文件和文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -empty</span></span></code></pre></div><p>使用以下命令组合查找 Linux 上包含特定文本的所有文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type f -exec grep &quot;Port 22&quot; &#39;{}&#39; \\; -print</span></span>
<span class="line"><span># find / -type f -print | xargs grep &quot;Port 22&quot;</span></span>
<span class="line"><span># find / -type f | xargs grep &#39;Port 22&#39;</span></span>
<span class="line"><span># find / -type f -exec grep -H &#39;Port 22&#39; {} \\;</span></span></code></pre></div><h3 id="方法-2-使用-locate-命令在-linux-中搜索文件和文件夹" tabindex="-1">方法 2：使用 locate 命令在 Linux 中搜索文件和文件夹 <a class="header-anchor" href="#方法-2-使用-locate-命令在-linux-中搜索文件和文件夹" aria-label="Permalink to “方法 2：使用 locate 命令在 Linux 中搜索文件和文件夹”">​</a></h3><p><code>locate</code> 命令比 <code>find</code> 命令运行得更快，因为它使用 <code>updatedb</code> 数据库，而 <code>find</code> 命令在真实系统中搜索。</p><p>它使用数据库而不是搜索单个目录路径来获取给定文件。</p><p><code>locate</code> 命令未在大多数发行版中预安装，因此，请使用你的包管理器进行安装。</p><p>数据库通过 cron 任务定期更新，但我们可以通过运行以下命令手动更新它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo updatedb</span></span></code></pre></div><p>只需运行以下命令即可列出给定的文件或文件夹。在 <code>locate</code> 命令中不需要指定特定选项来打印文件或文件夹。</p><p>在系统中搜索 <code>ssh</code> 文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># locate --basename &#39;\\ssh&#39;</span></span>
<span class="line"><span>/etc/ssh</span></span>
<span class="line"><span>/usr/bin/ssh</span></span>
<span class="line"><span>/usr/lib/ssh</span></span>
<span class="line"><span>/usr/lib/go/pkg/linux_amd64/cmd/vendor/golang.org/x/crypto/ssh</span></span>
<span class="line"><span>/usr/lib/go/src/cmd/go/testdata/failssh/ssh</span></span>
<span class="line"><span>/usr/lib/go/src/cmd/vendor/golang.org/x/crypto/ssh</span></span></code></pre></div><p>在系统中搜索 <code>ssh_config</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># locate --basename &#39;\\sshd_config&#39;</span></span>
<span class="line"><span>/etc/ssh/sshd_config</span></span></code></pre></div><h3 id="方法-3-在-linux-中搜索文件使用-which-命令" tabindex="-1">方法 3：在 Linux 中搜索文件使用 which 命令 <a class="header-anchor" href="#方法-3-在-linux-中搜索文件使用-which-命令" aria-label="Permalink to “方法 3：在 Linux 中搜索文件使用 which 命令”">​</a></h3><p><code>which</code> 返回在终端输入命令时执行的可执行文件的完整路径。</p><p>当你想要为可执行文件创建桌面快捷方式或符号链接时，它非常有用。</p><p><code>which</code> 命令搜索当前用户而不是所有用户的 <code>$PATH</code> 环境变量中列出的目录。我的意思是，当你登录自己的帐户时，你无法搜索 root 用户文件或目录。</p><p>运行以下命令以打印 <code>vim</code> 可执行文件的完整路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># which vi</span></span>
<span class="line"><span>/usr/bin/vi</span></span></code></pre></div><p>或者，它允许用户一次执行多个文件搜索。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># which -a vi sudo</span></span>
<span class="line"><span>/usr/bin/vi</span></span>
<span class="line"><span>/bin/vi</span></span>
<span class="line"><span>/usr/bin/sudo</span></span>
<span class="line"><span>/bin/sudo</span></span></code></pre></div><h3 id="方法-4-使用-whereis-命令在-linux-中搜索文件" tabindex="-1">方法 4：使用 whereis 命令在 Linux 中搜索文件 <a class="header-anchor" href="#方法-4-使用-whereis-命令在-linux-中搜索文件" aria-label="Permalink to “方法 4：使用 whereis 命令在 Linux 中搜索文件”">​</a></h3><p><code>whereis</code> 命令用于搜索给定命令的二进制、源码和手册页文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># whereis vi</span></span>
<span class="line"><span>vi: /usr/bin/vi /usr/share/man/man1/vi.1p.gz /usr/share/man/man1/vi.1.gz</span></span></code></pre></div><hr>`,39)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.2daygeek.com/four-easy-ways-to-search-or-find-files-and-folders-in-linux/"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/four-easy-ways-to-search-or-find-files-and-folders-in-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.2daygeek.com/author/prakash/"},{default:e(()=>[...s[2]||(s[2]=[a("Prakash Subramanian",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const v=t(h,[["render",c]]);export{y as __pageData,v as default};
